/**
 * The real launchAgent implementation p4-controller.mjs's runP4Task calls.
 *
 * Spawns the actual Pi runtime against the prepared worktree in --print
 * (non-interactive) mode, then reads back which model each active subagent
 * role actually ran with. See subagent-artifacts.mjs for what is and is not
 * independently verifiable from that readback.
 */
import { spawn } from "node:child_process";
import { agentInvocation } from "./agent.mjs";
import { privateDir, runPaths } from "./io.mjs";
import { readSubagentRoleResults } from "./subagent-artifacts.mjs";

function spawnToExit(command, args, options) {
  return new Promise((resolvePromise, rejectPromise) => {
    const child = spawn(command, args, options);
    child.on("error", rejectPromise);
    child.on("close", (code, signal) =>
      resolvePromise({ code: code ?? 1, signal: signal ?? null }),
    );
  });
}

/**
 * @param {object} manifest the loaded, validated P4 manifest
 * @param {string} state the P4 CLI's private state root (io.mjs stateRoot())
 */
export function createLaunchAgent({ manifest, state }) {
  return async function launchAgent({ worktree, prompt, env, run }) {
    const paths = runPaths(state, run.id);
    privateDir(paths.runDir);
    const main = manifest.roles.main;
    const [command, ...leadingArgs] = agentInvocation();
    const args = [
      ...leadingArgs,
      "--offline",
      "--approve",
      "--session",
      paths.session,
      "--session-dir",
      paths.runDir,
      "--name",
      run.id,
      "--model",
      main.model,
      "--thinking",
      main.thinking,
      "--print",
      prompt,
    ];
    const startedAt = Date.now();
    const result = await spawnToExit(command, args, {
      cwd: worktree,
      env,
      stdio: "ignore",
    });
    const durationMs = Date.now() - startedAt;
    if (result.code !== 0) {
      throw new Error(
        `P4 agent process for run '${run.id}' exited with code ${result.code}${
          result.signal ? ` (signal ${result.signal})` : ""
        }.`,
      );
    }
    const otherActiveRoles = Object.entries(manifest.roles)
      .filter(([role, pin]) => role !== "main" && pin.enabled !== false)
      .map(([role]) => role);
    const { resolvedRoles: subagentRoles, roleHistory } =
      readSubagentRoleResults(
        paths.runDir,
        run.id,
        otherActiveRoles,
        main.thinking,
      );
    return {
      resolvedRoles: {
        main: { model: main.model, thinking: main.thinking },
        ...subagentRoles,
      },
      roleHistory,
      sessionMetrics: { durationMs, exitCode: result.code },
      sessionPath: paths.session,
    };
  };
}
/**
 * Locating the agent module and its offline test seam.
 *
 * Mirrors benchmarks/harness/p3/agent.mjs: P4_AGENT_MODULE/P4_OFFLINE_TEST
 * are the only way to point a P4 run at a stub instead of the real,
 * globally installed Pi binary, and that override only works when the test
 * seam itself is explicitly enabled.
 */
import { existsSync, realpathSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";
import { GLOBAL_PI_BIN, SOURCE_ROOT } from "./config.mjs";

function fail(message) {
  throw new Error(message);
}

function defaultAgentModule() {
  const configured = process.env.P4_PI_BIN ?? GLOBAL_PI_BIN;
  if (!isAbsolute(configured) || !existsSync(configured)) {
    fail("P4_PI_BIN must name an existing absolute Pi executable.");
  }
  return realpathSync(configured);
}

export function isOfflineTest() {
  return process.env.P4_OFFLINE_TEST === "1";
}

export function agentModule() {
  const override = process.env.P4_AGENT_MODULE;
  if (!override) return defaultAgentModule();
  if (!isOfflineTest()) {
    fail("P4_AGENT_MODULE is reserved for the offline controller test.");
  }
  const candidate = resolve(override);
  const sourcePrefix = `${SOURCE_ROOT}/`;
  if (!candidate.startsWith(sourcePrefix) || !existsSync(candidate)) {
    fail(
      "P4_AGENT_MODULE must name an existing module inside the source checkout.",
    );
  }
  return candidate;
}

export function agentInvocation() {
  if (process.env.P4_AGENT_MODULE) return [process.execPath, agentModule()];
  return [agentModule()];
}
#!/usr/bin/env node
/**
 * P4 benchmark controller CLI entry point.
 *
 * RUNBOOK.md and any tooling should address `benchmarks/harness/p4.mjs`; the
 * implementation lives in p4/:
 *
 *   config.mjs              fixed paths and the launch pi binary location
 *   agent.mjs                locating the agent module and its offline test seam
 *   io.mjs                   private CLI state directory and per-run paths
 *   models.mjs                available-model discovery via `pi --list-models`
 *   subagent-artifacts.mjs   reading real per-role model/timing metadata
 *   launch.mjs                the real launchAgent p4-controller.mjs's runP4Task calls
 *   cli.mjs                   validate / run / summarize commands
 */
import { main } from "./p4/cli.mjs";

main(process.argv.slice(2)).catch((error) => {
  process.stderr.write(
    `P4: ${error instanceof Error ? error.message : String(error)}\n`,
  );
  process.exitCode = 1;
});

